const upsertDevice = `-- name: UpsertDevice :one
INSERT INTO devices (
    user_id, fingerprint, name, last_ip, last_location, is_trusted
) VALUES (
    $1, $2, $3, $4, $5, $6
)
ON CONFLICT (fingerprint) DO UPDATE
SET user_id = EXCLUDED.user_id,
    name = COALESCE(EXCLUDED.name, devices.name),
    last_ip = EXCLUDED.last_ip,
    last_location = EXCLUDED.last_location
RETURNING id, user_id, fingerprint, name, last_ip, last_location, is_trusted, created_at
`

type UpsertDeviceParams struct {
	UserID       uuid.UUID      `json:"user_id"`
	Fingerprint  string         `json:"fingerprint"`
	Name         sql.NullString `json:"name"`
	LastIp       sql.NullString `json:"last_ip"`
	LastLocation sql.NullString `json:"last_location"`
	IsTrusted    sql.NullBool   `json:"is_trusted"`
}

func (q *Queries) UpsertDevice(ctx context.Context, arg UpsertDeviceParams) (Device, error) {
	row := q.db.QueryRowContext(ctx, upsertDevice,
		arg.UserID,
		arg.Fingerprint,
		arg.Name,
		arg.LastIp,
		arg.LastLocation,
		arg.IsTrusted,
	)
	var i Device
	err := row.Scan(
		&i.ID,
		&i.UserID,
		&i.Fingerprint,
		&i.Name,
		&i.LastIp,
		&i.LastLocation,
		&i.IsTrusted,
		&i.CreatedAt,
	)
	return i, err
}

